using System;using System.Linq;using System.Drawing;using System.IO;using System.Collections.Generic;using System.Reflection;using System.Runtime.InteropServices;using System.Windows.Forms;using BeamScheduleFormatter;
class PowRecoveryUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static T Get<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(o,args);}[DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int msg,IntPtr a,IntPtr b);
 [STAThread]static void Main(){Application.EnableVisualStyles();AccessCodes.Granted=true;string dir=Path.Combine(Path.GetTempPath(),"DTCE-recovery-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string clean;using(var f=new ProgramOfWorksForm())clean=f.WorksProjectXml();using(var f=new ProgramOfWorksForm()){var t=new BackupTarget{SlotId="linked-only",Code="900",Description="Linked catalogue",Unit="m3",Row=10,Quantity=30};Get<List<BackupBillItem>>(f,"backupBill").Add(new BackupBillItem{Slot=t.SlotId,Signature=BackupMapping.Identity(t),Code=t.Code,Description=t.Description,Unit=t.Unit,Row=t.Row,WorkbookQuantity=t.Quantity});Get<PowSourceFiles>(f,"projectSourceFiles").Add(new PowSourceFile("Selected.xlsm","Excel workbook (imported original)",new byte[]{1,2,3}));f.OpenProjectXml(clean);Check(f.WorksValidationIssues().Count==0,"Link-only catalogue/reference state does not produce false opening/wall edit error");f.Show();var root=Get<TabControl>(f,"tabs");var rc=root.TabPages.Cast<TabPage>().Single(p=>p.Text=="Reinforced Concrete Works");root.SelectedTab=rc;var members=rc.Controls.OfType<TabControl>().Single();foreach(string caption in new[]{"Beam Estimate","Slab Estimate"}){members.SelectedTab=members.TabPages.Cast<TabPage>().Single(p=>p.Text==caption);Application.DoEvents();var child=members.SelectedTab.Controls.OfType<Form>().Single();var nav=child.Controls.OfType<TabControl>().Single();Check(nav.TabPages[0].Text=="Measurements","Input workspace is the first page for "+caption+" (first page: "+nav.TabPages[0].Text+")");Check(nav.TabCount>=4,"All workspace pages present for "+caption+" (pages: "+string.Join(", ",nav.TabPages.Cast<TabPage>().Select(p=>p.Text))+")");Check(nav.SelectedIndex==0,"Input workspace is selected for "+caption+" (selected index "+nav.SelectedIndex+")");Check(SendMessage(nav.Handle,0x1304,IntPtr.Zero,IntPtr.Zero).ToInt32()==nav.TabCount,"Native tab items match all managed workspace pages");Check(nav.TabPages[0].Controls.OfType<DataGridView>().Single().Visible,"Actual input table is visible for "+caption);Check(nav.Appearance==TabAppearance.Normal,"Original folder tab layout retained");}
 root.SelectedTab=root.TabPages.Cast<TabPage>().Single(p=>p.Text=="Bill of Quantities");Application.DoEvents();var boq=Get<DataGridView>(f,"boqGrid");boq.Rows.Clear();for(int n=0;n<400;n++)boq.Rows.Add(n,"Scroll row "+n,n,"m3");Application.DoEvents();BoqScrollState.EnsureEnd(boq);Application.DoEvents();var bounds=boq.GetRowDisplayRectangle(399,false);Check(boq.Rows[399].Displayed&&bounds.Bottom<=boq.ClientSize.Height,"Last BOQ row can be fully reached above the footer");var bar=f.Controls.Find("ExcelStatusBar",true).Single();Check(boq.RectangleToScreen(boq.ClientRectangle).Bottom<=bar.RectangleToScreen(bar.ClientRectangle).Top,"Status bar does not overlap the BOQ table");var steel=Get<DataGridView>(f,"steelAngles");int i=steel.Rows.Add();steel.Rows[i].Cells[1].Value="Auto ID angle";steel.Rows[i].Cells[2].Value="L75x75x5mm (PNS)";steel.Rows[i].Cells[3].Value="A36";steel.Rows[i].Cells[4].Value="10.322";steel.Rows[i].Cells[5].Value="1";f.Recalculate();Check(Convert.ToString(steel.Rows[i].Cells[0].Value).StartsWith("ANG-"),"Structural-steel blank ID is automatic");Check(Math.Abs(Convert.ToDouble(steel.Rows[i].Cells["AngleRequiredPieces"].Value)-10.322/6)<1e-8,"Required fractional pcs preserve installed length");Check(Convert.ToInt32(steel.Rows[i].Cells["AngleStocksOpened"].Value)==2,"Whole purchase stocks remain separate");int pending=steel.Rows.Add();steel.Rows[pending].Cells[1].Value="Pending angle";f.Recalculate();Check(f.WorksValidationIssues().Count>0,"Pending steel issue is retained");Check(!f.FinalQuantityTables().Any(x=>x.Name=="POW Input Issues"),"Partial export tables leave issues in the app");string path=Path.Combine(dir,"Partial.pow.xml");f.SaveTo(path);Check(File.ReadAllText(path).Contains("InputIssues"),"Partial save includes its issue list");var report=Call(f,"BuildQuantityEngineeringReport");Check(Convert.ToString(report.GetType().GetField("Status").GetValue(report)).StartsWith("Partial"),"Partial report is explicitly identified");}
 Console.WriteLine("PASS: "+checks+" native workspace recovery, linked-metadata Open, BOQ end-scroll, steel ID and partial-output checks");}finally{Directory.Delete(dir,true);}}
}
